/* ---------- interactive theory ---------- */
function gridClick(svgHost,cb){svgHost.addEventListener('click',e=>{const svg=svgHost.querySelector('svg');if(!svg)return;const r=svg.getBoundingClientRect();const vb=svg.viewBox.baseVal;
  const sx=(e.clientX-r.left)*vb.width/r.width,sy=(e.clientY-r.top)*vb.height/r.height;const pad=14,u=(vb.width-2*pad)/12;
  const x=Math.round((sx-pad)/u-6),y=Math.round(6-(sy-pad)/u);if(Math.abs(x)<=6&&Math.abs(y)<=6)cb(x,y);});}
function onTheory(root){
  const w=root.querySelector('#w-click');
  if(w){let pt=[3,2],sym=false;
    w.innerHTML=`<div id="wcS" style="display:flex;justify-content:center;cursor:crosshair"></div><div id="wcO" style="text-align:center;margin-top:6px;font-size:16px"></div><label style="justify-content:center"><input type="checkbox" id="wcC"> показать симметричные точки</label>`;
    const draw=()=>{const [x,y]=pt;const pts=[{x,y,l:`A${P(x,y)}`}];
      if(sym&&x&&y)pts.push({x,y:-y,l:'Ox',col:'var(--hl)'},{x:-x,y,l:'Oy',col:'var(--hl)'},{x:-x,y:-y,l:'O',col:'var(--hl)'});
      w.querySelector('#wcS').innerHTML=grid({xr:[-6,6],yr:[-6,6],w:300,pts,segs:[{a:[x,y],b:[x,0],dash:true,sw:1.2},{a:[x,y],b:[0,y],dash:true,sw:1.2}]});
      const q=quarter(x,y);w.querySelector('#wcO').innerHTML=`x = <span class="out">${N(x)}</span>, y = <span class="out">${N(y)}</span> — ${q<0?(x===0&&y===0?'начало координат':'точка на оси '+(x===0?'Oy':'Ox')):'<b>'+QN[q]+'</b> четверть'}${sym&&x&&y?`<br><span class="small">симметричные: Ox → ${P(x,-y)}, Oy → ${P(-x,y)}, O → ${P(-x,-y)}</span>`:''}`;};
    gridClick(w.querySelector('#wcS'),(x,y)=>{pt=[x,y];draw();});w.querySelector('#wcC').onchange=e=>{sym=e.target.checked;draw();};draw();}
  const b=root.querySelector('#w-battle');
  if(b){let ships,shots,log;const reset=()=>{ships=[];while(ships.length<3){const p=[R(-5,5),R(-5,5)];if(!ships.some(s=>s[0]===p[0]&&s[1]===p[1]))ships.push(p);}shots=[];log=[];};reset();
    b.innerHTML=`<div id="wbS" style="display:flex;justify-content:center;cursor:crosshair"></div><div id="wbO" style="text-align:center;margin-top:6px"></div><div class="row" style="margin-top:6px"><button class="btn ghost" id="wbN">Новая игра</button></div>`;
    const draw=()=>{const hits=shots.filter(s=>ships.some(p=>p[0]===s[0]&&p[1]===s[1]));const done=hits.length===3;
      const pts=shots.map(s=>{const h=ships.some(p=>p[0]===s[0]&&p[1]===s[1]);return {x:s[0],y:s[1],r:h?6:3,col:h?'var(--hl)':'var(--muted)'};});
      if(done)ships.forEach(p=>pts.push({x:p[0],y:p[1],r:6,col:'var(--hl)',l:'🚢'}));
      b.querySelector('#wbS').innerHTML=grid({xr:[-6,6],yr:[-6,6],w:300,pts});
      b.querySelector('#wbO').innerHTML=`Выстрелов: <span class="out">${shots.length}</span>, попаданий: <span class="out">${hits.length}</span> из 3${done?' — <b>все корабли потоплены! 🎉</b>':''}<br><span class="small">${log.slice(-4).join(' · ')}</span>`;};
    gridClick(b.querySelector('#wbS'),(x,y)=>{if(shots.some(s=>s[0]===x&&s[1]===y))return;if(shots.filter(s=>ships.some(p=>p[0]===s[0]&&p[1]===s[1])).length===3)return;shots.push([x,y]);const h=ships.some(p=>p[0]===x&&p[1]===y);log.push(`${P(x,y)} — ${h?'<b>попал!</b>':'мимо'}`);draw();});
    b.querySelector('#wbN').onclick=()=>{reset();draw();};draw();}
}

